let papers=[];let settings={};try{papers=JSON.parse(localStorage.getItem(key)||'null')||seeds;settings=JSON.parse(localStorage.getItem('folio-settings')||'{}')}catch{papers=seeds}
let view='library',collection='',query='',statusFilter='all',priorityFilter='all',sort='newest',layout='grid',recommendations=[],discoverState='',driveToken='',tokenExpiry=0,busy=false;
function enrichVenue(p){if(!p.rank && p.venue==='IEEE Symposium on Security and Privacy')Object.assign(p,{rank:'A*',metricType:'CORE rank',metricYear:'2023',metricSource:'https://portal.core.edu.au/conf-ranks/?by=all&search=security&source=CORE2023'});return p}
papers.forEach(enrichVenue);
const labels={library:'All papers',queue:'Reading queue',favorites:'Important papers',discover:'Discover',settings:'Settings & storage'};
function save(){localStorage.setItem(key,JSON.stringify(papers));updateSidebar()}
function saveSettings(){localStorage.setItem('folio-settings',JSON.stringify(settings))}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
function updateSidebar(){ $('#nav-total').textContent=papers.length;$('#nav-unread').textContent=papers.filter(p=>p.status==='unread').length;const tags=[...new Set([...papers.flatMap(p=>p.tags||[]),...(settings.collections||[])])];$('#collections').innerHTML=tags.map(t=>`<button class="collection" data-collection="${esc(t)}"><i></i>${esc(t)}<span>${papers.filter(p=>p.tags.includes(t)).length}</span></button>`).join('');$('#drive-connect').innerHTML=driveToken?'Google Drive connected <span>✓</span>':'Connect Google Drive <span>↗</span>';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); }
function navigate(next,tag=''){view=next;collection=tag;query='';statusFilter='all';priorityFilter='all';location.hash=tag?'collection='+encodeURIComponent(tag):next;render()}
function heading(title,description,actions=true){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL RESEARCH SPACE</div><h1>${esc(title)}</h1><p>${description}</p></div>${actions?`<div class="heading-actions"><button class="button" id="export-library">${icon('download')}<span class="export-text">Export citations</span></button><button class="button primary" id="add-paper">${icon('plus')}Add paper</button></div>`:''}</div>`}
function card(p,external=false){const metric=p.rank?`${esc(p.metricType||'Rank')} ${esc(p.rank)} · ${esc(p.metricYear||'')}`:'Venue metrics not recorded';return `<article class="paper-card"><div class="card-top"><span class="badge ${p.status}"><i></i>${external?'DISCOVERED':p.status==='read'?'Read':p.status==='reading'?'Reading':'Unread'}</span>${external?`<button class="star-button" data-import="${esc(p.id)}" title="Add to library" aria-label="Add ${esc(p.title)} to library">+</button>`:`<button class="star-button ${p.importance==='high'?'on':''}" data-star="${esc(p.id)}" aria-label="${p.importance==='high'?'Remove importance from':'Mark important:'} ${esc(p.title)}">${p.importance==='high'?'★':'☆'}</button>`}</div><button class="paper-title" ${external?'data-external':'data-paper'}="${esc(p.id)}">${esc(p.title)}</button><div class="authors">${esc(p.authors||'Authors not recorded')}</div><div class="tags">${(p.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span class="venue" title="${esc(p.venue)}">${icon('venue')}${esc(p.venue||'Venue not recorded')}</span><span class="paper-year">${p.pdfId?icon('file'):icon('link')}${esc(p.year||'—')}</span></div><div class="metric-line">${metric}</div></article>`}
function filtered(){let list=papers.filter(p=>(view!=='queue'||p.status==='unread')&&(view!=='favorites'||p.importance==='high')&&(!collection||p.tags.includes(collection))&&(statusFilter==='all'||p.status===statusFilter)&&(priorityFilter==='all'||p.importance===priorityFilter)&&`${p.title} ${p.authors} ${p.venue} ${p.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return list.sort((a,b)=>sort==='oldest'?a.added-b.added:sort==='year'?(b.year||0)-(a.year||0):sort==='title'?a.title.localeCompare(b.title):sort==='importance'?({high:2,normal:1,low:0}[b.importance]-{high:2,normal:1,low:0}[a.importance])||b.added-a.added:b.added-a.added)}
function renderPapers(){const list=filtered();$('#paper-results').innerHTML=list.length?list.map(p=>card(p)).join(''):`<div class="empty">${icon('book')}<h3>A little room for discovery.</h3><p>${papers.length?'No papers match these filters.':'Add your first paper to begin your library.'}</p><button class="button" id="empty-add">${icon('plus')}Add a paper</button></div>`;$('#result-count').textContent=`${list.length} papers`;}
function render(){updateSidebar();$('#breadcrumb').textContent=collection||labels[view];if(view==='settings'){renderSettings();return}if(view==='discover'){renderDiscover();return}const unread=papers.filter(p=>p.status==='unread').length;const title=collection||labels[view];$('#main').innerHTML=heading(title,view==='queue'?'Turn your reading list into your next great idea.':view==='favorites'?'The papers you want to keep close.':'A home for the ideas that move your research forward.')+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('spark')} A LITTLE DIRECTION FOR YOUR NEXT READ</div><h2>${view==='queue'?'Good research starts with one paper.':'Your next idea is waiting in your library.'}</h2><p>${unread?`You have ${unread} unread papers. Let’s find a good place to start.`:'Your reading queue is clear. Discover something new to explore.'}</p><button class="button" id="pick-paper">${icon('book')}${unread?'Pick my next read':'Discover papers'} ${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Prefer important papers</label><label><input id="random-pick" type="checkbox"> Surprise me</label></div>':''}</div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="art-ring second"></div><div class="book-cover"></div><div class="book-front"><small>COLLECTED IDEAS</small><em>A world<br>of possibility.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><div class="stats">${[[papers.length,'Total papers','library'],[unread,'Waiting to be read','clock'],[papers.filter(p=>p.status==='read').length,'Papers read','check'],[papers.filter(p=>p.importance==='high').length,'Important papers','star']].map(([n,l,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><small>${l}</small></div></div>`).join('')}</div><div class="section-title"><h2>${collection|| (view==='queue'?'Your unread papers':view==='favorites'?'Your important papers':'Your library')}<span id="result-count"></span></h2><span class="subtle-link">Small steps. New perspectives.</span></div><div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Search by title, author, or keyword…" aria-label="Search papers" value="${esc(query)}"></label><select id="status-filter" aria-label="Filter reading status"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select><select id="priority-filter" aria-label="Filter importance"><option value="all">All importance</option><option value="high">High importance</option><option value="normal">Normal importance</option><option value="low">Low importance</option></select><select id="sort" aria-label="Sort papers"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select><div class="view-toggle"><button data-layout="grid" class="${layout==='grid'?'selected':''}" aria-label="Grid view">${icon('grid')}</button><button data-layout="list" class="${layout==='list'?'selected':''}" aria-label="List view">${icon('list')}</button></div></div><div class="paper-grid ${layout==='list'?'list':''}" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Explore with a sample library. Your own papers belong here, too.</span><button id="remove-samples">Remove sample papers</button></div>':''}`;renderPapers();$('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;$('#search').oninput=e=>{query=e.target.value;renderPapers()};['status','priority'].forEach(type=>$('#'+type+'-filter').onchange=e=>{if(type==='status')statusFilter=e.target.value;else priorityFilter=e.target.value;renderPapers()});$('#sort').onchange=e=>{sort=e.target.value;renderPapers()};}
function modal(html,reader=false){$('#modal').classList.toggle('reader-modal',reader);$('#modal-content').innerHTML=`<div class="modal-inner">${html}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function close(){if(readerUrl){URL.revokeObjectURL(readerUrl);readerUrl=''}$('#modal').close()}
function modalTitle(title){return `<div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>`}
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('folio-pdfs',1);req.onupgradeneeded=()=>req.result.createObjectStore('pdfs');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});dbPromise.catch(()=>{});
async function pdfStore(action,id,value){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('pdfs',action==='get'?'readonly':'readwrite');const store=tx.objectStore('pdfs');const req=action==='get'?store.get(id):action==='delete'?store.delete(id):store.put(value,id);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
let addMode='url',selectedFile=null,readerUrl='';
function addPaper(){selectedFile=null;addMode='url';renderAdd()}
function renderAdd(){modal(modalTitle('Make room for a new idea.')+`<p style="font-size:12px">Add a paper from a link, a PDF, or your own citation details.</p><div class="tabs"><button data-add-tab="url" class="${addMode==='url'?'active':''}">Paper URL / DOI</button><button data-add-tab="pdf" class="${addMode==='pdf'?'active':''}">Upload PDF</button><button data-add-tab="manual" class="${addMode==='manual'?'active':''}">Manual entry</button></div><form id="add-form">${addMode==='url'?'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="https://eprint.iacr.org/2019/953 or 10.1137/0218012"><small>IACR ePrint, arXiv, publisher links, or a DOI. DOI metadata comes from Crossref; other links can be saved with your own details.</small></div><button type="button" class="button" id="lookup">'+icon('search')+'Look up DOI metadata</button>':addMode==='pdf'?`<label class="upload-zone" for="pdf-upload" style="display:block">${icon('upload')}<p id="file-label">Choose a PDF to add to your library</p><small>PDF files up to 50 MB · Stored on this device</small></label><input id="pdf-upload" type="file" accept="application/pdf,.pdf" hidden>`:''}<div class="field"><label for="paper-title">Title *</label><input id="paper-title" required maxlength="500" placeholder="The title of the paper"></div><div class="field"><label for="paper-authors">Authors</label><input id="paper-authors" placeholder="Separate authors with semicolons"></div><div class="two-fields"><div class="field"><label for="paper-year">Publication year</label><input id="paper-year" type="number" min="1400" max="2100" placeholder="2026"></div><div class="field"><label for="paper-venue">Conference / journal</label><input id="paper-venue" placeholder="e.g. EUROCRYPT"></div></div><div class="field"><label for="paper-tags">Collections / tags</label><input id="paper-tags" placeholder="Cryptography, Zero knowledge"></div><div class="two-fields"><div class="field"><label for="paper-status">Reading status</label><select id="paper-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="paper-priority">Importance</label><select id="paper-priority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></div></div><div id="add-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary" id="save-paper" type="submit">${icon('plus')}Add to library</button></div></form>`);if(addMode==='pdf')$('#pdf-upload').onchange=e=>{selectedFile=e.target.files[0];if(selectedFile){$('#file-label').textContent=selectedFile.name;$('#paper-title').value=selectedFile.name.replace(/\.pdf$/i,'').replace(/[_-]/g,' ')}};$('#add-form').onsubmit=submitAdd;if($('#lookup'))$('#lookup').onclick=lookupMetadata;}
function getDoi(value){const clean=value.trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').replace(/^doi:\s*/i,'');return /^10\.\d{4,9}\/\S+$/i.test(clean)?clean:''}
async function fetchJson(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error(`Service returned ${r.status}. Please try again.`);return r.json()}
function crossrefPaper(w){return {id:crypto.randomUUID(),title:w.title?.[0]||'Untitled paper',authors:(w.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join('; '),year:(w.published?.['date-parts']||w.issued?.['date-parts'])?.[0]?.[0]||'',venue:w['container-title']?.[0]||'',doi:w.DOI||'',url:w.URL||'',tags:[],status:'unread',importance:'normal',notes:'',added:Date.now(),updated:Date.now(),metadataSource:'Crossref',type:w.type}}
async function lookupMetadata(){const doi=getDoi($('#paper-url').value);if(!doi){$('#add-error').textContent='This link has no DOI. Enter the citation details below, or paste a DOI to look it up.';return}const b=$('#lookup');b.disabled=true;b.textContent='Looking up…';try{const p=crossrefPaper((await fetchJson('https://api.crossref.org/works/'+encodeURIComponent(doi))).message);$('#paper-title').value=p.title;$('#paper-authors').value=p.authors;$('#paper-year').value=p.year;$('#paper-venue').value=p.venue;$('#add-error').textContent='';toast('Citation details found. Review before saving.')}catch(e){$('#add-error').textContent=e.message+' You can still enter details manually.'}finally{b.disabled=false;b.innerHTML=icon('search')+'Look up DOI metadata'}}
async function submitAdd(e){e.preventDefault();const error=$('#add-error');const b=$('#save-paper');b.disabled=true;try{const source=$('#paper-url')?.value.trim()||'';const doi=getDoi(source);if(source&&!doi&&!safeUrl(source))throw new Error('Enter a valid http or https paper URL.');if(addMode==='pdf'&&!selectedFile)throw new Error('Choose a PDF first.');if(selectedFile){if(selectedFile.size>50*1024*1024)throw new Error('Please choose a PDF smaller than 50 MB.');const bytes=await selectedFile.slice(0,5).text();if(bytes!=='%PDF-')throw new Error('This file does not appear to be a valid PDF.');}if(doi&&papers.some(p=>p.doi?.toLowerCase()===doi.toLowerCase()))throw new Error('This DOI is already in your library.');const p={id:crypto.randomUUID(),title:$('#paper-title').value.trim(),authors:$('#paper-authors').value.trim(),year:Number($('#paper-year').value)||'',venue:$('#paper-venue').value.trim(),tags:$('#paper-tags').value.split(',').map(t=>t.trim()).filter(Boolean),status:$('#paper-status').value,importance:$('#paper-priority').value,url:doi?'https://doi.org/'+doi:source,doi,notes:'',added:Date.now(),updated:Date.now()};if(!p.title)throw new Error('Enter a paper title.');if(selectedFile){p.pdfId=p.id;p.pdfName=selectedFile.name;await pdfStore('put',p.pdfId,selectedFile)}papers.unshift(enrichVenue(p));save();close();render();toast('Paper added. A new idea, collected.')}catch(err){error.textContent=err.message}finally{b.disabled=false}}
function details(id,external=false){const p=(external?recommendations:papers).find(p=>p.id===id);if(!p)return;modal(modalTitle(p.title)+`<p style="font-size:12px">${esc(p.authors)} · ${esc(p.year||'Year not recorded')}</p><div class="detail-links">${p.pdfId||p.drivePdfId?`<button class="button primary" data-read="${esc(p.id)}">${icon('book')}Read PDF</button>`:''}${safeUrl(p.url|| (p.doi?'https://doi.org/'+p.doi:''))?`<a class="button" href="${esc(safeUrl(p.url||'https://doi.org/'+p.doi))}" target="_blank" rel="noopener noreferrer">${icon('link')}Open paper ↗</a>`:''}${!external?`<button class="button" data-cite="${esc(p.id)}">${icon('download')}Cite</button>`:''}</div>${external?`<p>Found via Crossref. Check the publisher page for the full text and publication details.</p><div class="modal-actions"><button class="button primary" data-import="${esc(p.id)}">Add to library</button></div>`:`<form id="detail-form"><div class="two-fields"><div class="field"><label for="detail-status">Reading status</label><select id="detail-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="detail-priority">Importance</label><select id="detail-priority"><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select></div></div><div class="field"><label for="detail-title">Title</label><input id="detail-title" value="${esc(p.title)}" required></div><div class="field"><label for="detail-authors">Authors</label><input id="detail-authors" value="${esc(p.authors)}"></div><div class="two-fields"><div class="field"><label for="detail-year">Publication year</label><input id="detail-year" type="number" min="1400" max="2100" value="${esc(p.year)}"></div><div class="field"><label for="detail-venue">Conference / journal</label><input id="detail-venue" value="${esc(p.venue)}"></div></div><div class="field"><label for="detail-tags">Collections / tags</label><input id="detail-tags" value="${esc(p.tags.join(', '))}"></div><div class="field"><label for="detail-notes">Reading notes</label><textarea id="detail-notes" placeholder="Key ideas, questions, and things to come back to…">${esc(p.notes)}</textarea></div><details><summary style="font-size:12px;cursor:pointer">Venue rank & impact factor</summary><p style="font-size:11px">Record a metric from a source such as CORE or Journal Citation Reports. These are venue metrics; they are not a score for this paper.</p><div class="two-fields"><div class="field"><label for="metric-type">Metric</label><select id="metric-type"><option>CORE rank</option><option>Journal impact factor</option><option>SJR quartile</option></select></div><div class="field"><label for="metric-value">Value</label><input id="metric-value" value="${esc(p.rank||'')}" placeholder="e.g. A* or 4.2"></div></div><div class="two-fields"><div class="field"><label for="metric-year">Metric year</label><input id="metric-year" type="number" min="2000" max="2100" value="${esc(p.metricYear||'')}" placeholder="2025"></div><div class="field"><label for="metric-source">Source URL</label><input id="metric-source" type="url" value="${esc(p.metricSource||'')}" placeholder="https://…"></div></div>${safeUrl(p.metricSource)?`<a href="${esc(p.metricSource)}" target="_blank" rel="noopener noreferrer" style="font-size:11px">View recorded source ↗</a>`:''}</details><div id="detail-error" class="error"></div><div class="modal-actions"><button type="button" class="button danger" data-delete="${esc(p.id)}">Remove paper</button><button class="button primary" type="submit">Save changes</button></div></form>`}`);if(!external){$('#detail-status').value=p.status;$('#detail-priority').value=p.importance;$('#metric-type').value=p.metricType||'CORE rank';$('#detail-form').onsubmit=e=>{e.preventDefault();const rank=$('#metric-value').value.trim();if(rank&&(!$('#metric-year').value||!safeUrl($('#metric-source').value))){$('#detail-error').textContent='Add a year and a valid source URL for the venue metric.';return}Object.assign(p,{title:$('#detail-title').value.trim(),authors:$('#detail-authors').value.trim(),year:Number($('#detail-year').value)||'',venue:$('#detail-venue').value.trim(),status:$('#detail-status').value,importance:$('#detail-priority').value,tags:$('#detail-tags').value.split(',').map(t=>t.trim()).filter(Boolean),notes:$('#detail-notes').value,rank,metricType:$('#metric-type').value,metricYear:$('#metric-year').value,metricSource:$('#metric-source').value,updated:Date.now()});save();close();render();toast('Paper updated.')};}}
async function readPdf(id){try{const p=papers.find(p=>p.id===id);let blob=p.pdfId?await pdfStore('get',p.pdfId):null;if(!blob&&p.drivePdfId){if(!driveToken)throw new Error('Connect Google Drive in Settings to download this PDF.');const r=await driveFetch('/files/'+encodeURIComponent(p.drivePdfId)+'?alt=media');blob=await r.blob();p.pdfId=p.id;await pdfStore('put',p.pdfId,blob);save()}if(!blob)throw new Error('This PDF is not on this device. Restore from Drive or upload it again.');if(readerUrl)URL.revokeObjectURL(readerUrl);readerUrl=URL.createObjectURL(blob);modal(modalTitle(p.title)+`<div class="detail-links"><a class="button" href="${readerUrl}" target="_blank">Open in new tab ↗</a><a class="button" href="${readerUrl}" download="${esc(p.pdfName||'paper.pdf')}">Download PDF</a><button class="button primary" id="reader-mark">Mark as read</button></div><iframe class="reader" title="PDF reader" src="${readerUrl}"></iframe>`,true);$('#reader-mark').onclick=()=>{p.status='read';p.updated=Date.now();save();render();toast('Marked as read.')}}catch(e){toast(e.message)}}
function bibEscape(s){return String(s||'').replace(/[\\{}%&#_$]/g,c=>'\\'+c)}
function citation(p,format){const isConference=/proceedings|conference|symposium|EUROCRYPT/i.test(p.type||p.venue);const authors=p.authors.split(';').map(a=>a.trim()).filter(Boolean);if(format==='plain')return `${authors.join(', ')}${p.year?' ('+p.year+').':'.'} ${p.title}. ${p.venue||''}.${p.doi?' https://doi.org/'+p.doi:p.url?' '+p.url:''}`;if(format==='ris')return `TY  - ${isConference?'CPAPER':'JOUR'}\nTI  - ${p.title}\n${authors.map(a=>'AU  - '+a).join('\n')}\nPY  - ${p.year}\nJO  - ${p.venue}\nDO  - ${p.doi||''}\nUR  - ${p.url||''}\nER  -`;const name=authors[0]?.split(' ').at(-1)?.replace(/[^a-zA-Z]/g,'')||'paper';return `@${isConference?'inproceedings':'article'}{${name}${p.year||''}_${p.id.slice(-4)},\n  title = {${bibEscape(p.title)}},\n  author = {${authors.map(bibEscape).join(' and ')}},\n  year = {${p.year}},\n  ${isConference?'booktitle':'journal'} = {${bibEscape(p.venue)}}${p.doi?',\n  doi = {'+bibEscape(p.doi)+'}':''}${p.url?',\n  url = {'+bibEscape(p.url)+'}':''}\n}`}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function cite(id){const list=id?papers.filter(p=>p.id===id):papers;let format='bibtex';modal(modalTitle(id?'A citation, ready to go.':'Export your library.')+`<div class="field"><label for="cite-format">Citation format</label><select id="cite-format"><option value="bibtex">BibTeX</option><option value="ris">RIS</option><option value="plain">Plain text</option></select></div><p style="font-size:11px">${list.length} ${list.length===1?'paper':'papers'} · Review metadata for your preferred citation style.</p><pre class="citation-block" id="citation-output"></pre><div class="modal-actions"><button class="button" id="copy-citation">Copy citations</button><button class="button primary" id="download-citation">${icon('download')}Download</button></div>`);const content=()=>list.map(p=>citation(p,format)).join('\n\n');$('#citation-output').textContent=content();$('#cite-format').onchange=e=>{format=e.target.value;$('#citation-output').textContent=content()};$('#copy-citation').onclick=async()=>{try{await navigator.clipboard.writeText(content());toast('Citations copied.')}catch{toast('Clipboard unavailable. Use Download instead.')}};$('#download-citation').onclick=()=>download('folio-citations.'+({bibtex:'bib',ris:'ris',plain:'txt'}[format]),content())}
function pickPaper(){const list=filtered().filter(p=>p.status==='unread');if(!list.length){if(papers.some(p=>p.status==='unread'))toast('No unread papers match your current filters.');else navigate('discover');return}let candidates=list;if($('#prefer-important')?.checked!==false){const high=list.filter(p=>p.importance==='high');if(high.length)candidates=high}const chosen=$('#random-pick')?.checked?candidates[Math.floor(Math.random()*candidates.length)]:[...candidates].sort((a,b)=>a.added-b.added)[0];details(chosen.id);toast('Picked from your unread papers.')}
function renderDiscover(){const tags=[...new Set(papers.flatMap(p=>p.tags))].slice(0,4);$('#main').innerHTML=heading('Follow your curiosity.','Find papers beyond your library, guided by what interests you.',false)+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('compass')} OPEN A NEW CHAPTER</div><h2>There’s always another idea to explore.</h2><p>Search live scholarly metadata, or use your library’s topics as a starting point.</p><button class="button" id="recommend">${icon('spark')}Recommend from my interests ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="book-cover"></div><div class="book-front"><small>NEW PERSPECTIVES</small><em>Stay<br>curious.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><form class="discover-search" id="discover-form"><label class="search">${icon('search')}<input id="discover-query" placeholder="Explore a topic, title, or author…" aria-label="Search scholarly papers" required></label><button class="button primary" id="discover-submit">Find papers</button></form><div class="tags">${tags.map(t=>`<button class="button" data-discover-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="section-title"><h2>Beyond your library</h2><span class="subtle-link">Live metadata by Crossref</span></div><div id="discover-message" class="discover-message">${esc(discoverState||'Choose a topic to discover papers. Recommendations appear only when you ask.')}</div><div id="discover-results" class="paper-grid">${recommendations.map(p=>card(p,true)).join('')}</div>`;$('#discover-form').onsubmit=e=>{e.preventDefault();searchDiscovery($('#discover-query').value)};$('#recommend').onclick=()=>{const interests=papers.filter(p=>p.importance==='high').flatMap(p=>p.tags);const topic=[...new Set(interests)].slice(0,2).join(' ')||tags.slice(0,2).join(' ');if(!topic){toast('Add tags to your papers, or search a topic.');return}$('#discover-query').value=topic;searchDiscovery(topic)};}
let searchSequence=0;
async function searchDiscovery(topic){const seq=++searchSequence;const b=$('#discover-submit');b.disabled=true;$('#discover-message').textContent='Looking for new perspectives…';try{const data=await fetchJson('https://api.crossref.org/works?query.bibliographic='+encodeURIComponent(topic)+'&rows=40');if(seq!==searchSequence||view!=='discover')return;const existing=new Set(papers.map(p=>(p.doi||'').toLowerCase()));const titles=new Set(papers.map(p=>p.title.toLowerCase()));const seen=new Set();recommendations=data.message.items.filter(w=>['journal-article','proceedings-article','posted-content','dissertation'].includes(w.type)).map(crossrefPaper).filter(p=>!existing.has(p.doi.toLowerCase())&&!titles.has(p.title.toLowerCase())).filter(p=>{const t=p.title.toLowerCase();if(seen.has(t))return false;seen.add(t);return true}).slice(0,12).map(p=>({...p,tags:[topic.length>35?'Related research':topic]}));discoverState=`${recommendations.length} papers related to “${topic}” · Papers already in your library are excluded.`;$('#discover-message').textContent=discoverState;$('#discover-results').innerHTML=recommendations.length?recommendations.map(p=>card(p,true)).join(''):'<div class="empty">No new papers found. Try a broader topic.</div>'}catch(e){if(view==='discover'&&seq===searchSequence){$('#discover-message').textContent=e.message+' Your existing results are still shown.'}}finally{b.disabled=false}}
function importPaper(id){const p=recommendations.find(p=>p.id===id);if(!p)return;if(papers.some(a=>a.doi&&a.doi===p.doi)){toast('Already in your library.');return}papers.unshift(enrichVenue({...p,added:Date.now(),updated:Date.now()}));recommendations=recommendations.filter(a=>a.id!==id);save();close();render();toast('A new perspective added to your library.')}
function renderSettings(){const connected=driveToken&&Date.now()<tokenExpiry;$('#main').innerHTML=heading('Your library, your way.','Manage storage, Google Drive, and library backups.',false)+`<section class="panel"><h2>${icon('drive')} Google Drive</h2><p>Back up your library data and uploaded PDFs to a dedicated <strong>Folio Library</strong> folder in your Drive. Connect your Google account, then choose when to back up or restore. Your library remains available on this device.</p><div class="field"><label for="google-client">Google OAuth client ID</label><input id="google-client" value="${esc(settings.clientId||'')}" placeholder="…apps.googleusercontent.com"><small>This is a public web client ID, not a client secret.</small></div><div class="setting-row"><button id="google-connect" class="button primary">${icon('drive')}${connected?'Reconnect Google Drive':'Connect Google Drive'}</button>${connected?'<button id="google-disconnect" class="button">Disconnect</button>':''}<span style="font-size:11px;color:#91a080">${connected?'Connected for this session':'Not connected'}</span></div><div class="setting-row"><button id="drive-backup" class="button" ${connected?'':'disabled'}>${icon('upload')}Back up to Drive</button><button id="drive-restore" class="button" ${connected?'':'disabled'}>${icon('download')}Restore / merge from Drive</button></div><p id="drive-progress" style="font-size:11px" role="status">${settings.lastBackup?'Last backup: '+esc(new Date(settings.lastBackup).toLocaleString()):'No Drive backup yet.'}</p><details style="margin-top:22px"><summary style="font-size:12px;cursor:pointer">First-time Google Drive setup</summary><div class="help" style="margin-top:15px"><ol><li>In <a href="https://console.cloud.google.com/apis/library/drive.googleapis.com" target="_blank" rel="noopener noreferrer">Google Cloud Console</a>, create a project and enable the Google Drive API.</li><li>Configure the OAuth consent screen. For a testing app, add your Google account as a test user.</li><li>Create an OAuth client of type <strong>Web application</strong>.</li><li>Add this exact Authorized JavaScript origin: <code>${esc(location.origin)}</code></li><li>Paste the client ID above and select Connect Google Drive. Allow access to files created by this app.</li></ol><p>Folio requests the limited <code>drive.file</code> scope. Access tokens stay in memory and expire; reconnect to continue. <a href="https://developers.google.com/identity/oauth2/web/guides/use-token-model" target="_blank" rel="noopener noreferrer">Google authorization guide ↗</a></p></div></details></section><section class="panel"><h2>Local backup & recovery</h2><p>Your papers and notes are saved in this browser; uploaded PDFs are stored in IndexedDB. Export a backup before clearing browser data. JSON exports contain citation data and notes; use Drive backup to include PDF files.</p><div class="setting-row"><button id="json-export" class="button">${icon('download')}Export library JSON</button><button id="json-import" class="button">${icon('upload')}Import library JSON</button><input type="file" id="json-file" accept="application/json,.json" hidden><button id="settings-cite" class="button">Export citations</button></div></section>${papers.some(p=>p.sample)?'<section class="panel danger-zone"><div><h2>Make it your own</h2><p>Remove the sample papers to start with your own research.</p></div><button class="button danger" id="remove-samples">Remove samples</button></section>':''}`;$('#google-connect').onclick=connectDrive;$('#drive-backup').onclick=backupDrive;$('#drive-restore').onclick=restoreDrive;if($('#google-disconnect'))$('#google-disconnect').onclick=()=>{if(window.google&&driveToken)google.accounts.oauth2.revoke(driveToken,()=>{});driveToken='';tokenExpiry=0;render();toast('Google Drive disconnected.')};$('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');$('#json-import').onclick=()=>$('#json-file').click();$('#settings-cite').onclick=()=>cite();$('#json-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));save();render();toast('Library backup merged.')}catch(err){toast('Import failed: '+err.message)}};}
async function connectDrive(){const clientId=$('#google-client').value.trim();if(!clientId.endsWith('.apps.googleusercontent.com')){toast('Enter a Google web OAuth client ID first.');return}settings.clientId=clientId;saveSettings();if(!window.google?.accounts?.oauth2){toast('Google sign-in is still loading or blocked. Try again.');return}google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/drive.file',callback:r=>{if(r.error){toast('Google authorization failed: '+r.error);return}if(!google.accounts.oauth2.hasGrantedAllScopes(r,'https://www.googleapis.com/auth/drive.file')){toast('Drive file permission was not granted.');return}driveToken=r.access_token;tokenExpiry=Date.now()+Number(r.expires_in)*1000;render();toast('Google Drive connected. Choose Back up or Restore.');},error_callback:e=>toast('Google connection did not finish: '+(e.type||'popup closed'))}).requestAccessToken({prompt:'consent'})}
async function driveFetch(path,options={}){if(!driveToken||Date.now()>=tokenExpiry){driveToken='';throw new Error('Your Google session expired. Reconnect in Settings.')}const r=await fetch((path.startsWith('https://www.googleapis.com/')?path:'https://www.googleapis.com/drive/v3'+path),{...options,headers:{...options.headers,Authorization:'Bearer '+driveToken},signal:AbortSignal.timeout(90000)});if(!r.ok){if(r.status===401){driveToken='';tokenExpiry=0}const body=await r.json().catch(()=>({}));throw new Error(body.error?.message||'Drive request failed ('+r.status+').')}return r}
async function driveList(q){return (await(await driveFetch('/files?q='+encodeURIComponent(q+' and trashed = false')+'&fields=files(id,name)&pageSize=100')).json()).files}
async function driveFolder(create){const found=await driveList("name = 'Folio Library' and mimeType = 'application/vnd.google-apps.folder'");if(found.length>1)throw new Error('Multiple Folio Library folders found. Rename duplicates in Drive before continuing.');if(found.length)return found[0].id;if(!create)throw new Error('No Folio Library backup folder found in this Google account.');return (await(await driveFetch('/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Folio Library',mimeType:'application/vnd.google-apps.folder'})})).json()).id}
async function driveUpload(blob,name,folder,id){const path='https://www.googleapis.com/upload/drive/v3/files'+(id?'/'+encodeURIComponent(id):'')+'?uploadType=resumable&fields=id';const metadata=id?{name}:{name,parents:[folder]};const init=await driveFetch(path,{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json','X-Upload-Content-Type':blob.type||'application/octet-stream'},body:JSON.stringify(metadata)});const uploadUrl=init.headers.get('Location');if(!uploadUrl?.startsWith('https://www.googleapis.com/'))throw new Error('Drive did not provide a valid upload session.');return (await(await driveFetch(uploadUrl,{method:'PUT',headers:{'Content-Type':blob.type||'application/octet-stream'},body:blob})).json()).id}
async function driveOperation(action){if(busy)return;busy=true;$('#drive-backup').disabled=true;$('#drive-restore').disabled=true;try{await action()}catch(e){($('#drive-progress')||{}).textContent=e.message;toast('Drive operation failed. Your local library is safe.')}finally{busy=false;if($('#drive-backup')){$('#drive-backup').disabled=!driveToken;$('#drive-restore').disabled=!driveToken}}}
async function backupDrive(){await driveOperation(async()=>{const folder=await driveFolder(true);const files=await driveList("'"+folder+"' in parents");const snapshot=structuredClone(papers);for(let i=0;i<snapshot.length;i++){const p=snapshot[i];if(!p.pdfId)continue;($('#drive-progress')||{}).textContent=`Backing up PDFs… ${i+1} / ${snapshot.length}`;const blob=await pdfStore('get',p.pdfId);if(!blob){if(!p.drivePdfId)throw new Error('PDF missing on this device: '+p.title);continue}const name=p.id+'.pdf';const existing=files.find(f=>f.name===name);p.drivePdfId=await driveUpload(blob,name,folder,existing?.id);const local=papers.find(a=>a.id===p.id);if(local)local.drivePdfId=p.drivePdfId;save()}($('#drive-progress')||{}).textContent='Saving library metadata…';const existing=files.find(f=>f.name==='library.json');await driveUpload(new Blob([JSON.stringify({version:1,papers:snapshot,exported:new Date().toISOString()})],{type:'application/json'}),'library.json',folder,existing?.id);settings.lastBackup=Date.now();saveSettings();($('#drive-progress')||{}).textContent='Backup complete. Library and available PDFs saved to Google Drive.';toast('Google Drive backup complete.')})}
function validateBackup(data){if(data?.version!==1||!Array.isArray(data.papers)||data.papers.length>10000)throw new Error('Not a supported Folio library backup.');return data.papers.map(p=>{if(typeof p.id!=='string'||p.id.length>100||!p.id||typeof p.title!=='string'||!p.title.trim())throw new Error('Invalid paper record.');return {id:p.id,title:p.title.slice(0,500),authors:String(p.authors||'').slice(0,5000),year:Number(p.year)||'',venue:String(p.venue||'').slice(0,1000),tags:Array.isArray(p.tags)?p.tags.filter(t=>typeof t==='string').slice(0,50):[],status:['read','unread','reading'].includes(p.status)?p.status:'unread',importance:['high','normal','low'].includes(p.importance)?p.importance:'normal',url:safeUrl(p.url),doi:getDoi(String(p.doi||'')),notes:String(p.notes||'').slice(0,100000),added:Number(p.added)||Date.now(),updated:Number(p.updated)||Number(p.added)||Date.now(),sample:p.sample===true,pdfId:typeof p.pdfId==='string'?p.pdfId:undefined,pdfName:String(p.pdfName||''),drivePdfId:typeof p.drivePdfId==='string'?p.drivePdfId:undefined,rank:String(p.rank||''),metricType:String(p.metricType||''),metricYear:String(p.metricYear||''),metricSource:safeUrl(p.metricSource),type:String(p.type||'')}})}
function mergeBackup(data){const incoming=validateBackup(data);const map=new Map(papers.map(p=>[p.id,p]));for(const p of incoming){const current=map.get(p.id);if(!current)map.set(p.id,p);else if(p.updated>current.updated)map.set(p.id,{...p,pdfId:current.pdfId||p.pdfId});else if(p.drivePdfId&&!current.drivePdfId)current.drivePdfId=p.drivePdfId}papers=[...map.values()]}
async function restoreDrive(){await driveOperation(async()=>{($('#drive-progress')||{}).textContent='Reading Drive backup…';const folder=await driveFolder(false);const files=await driveList("'"+folder+"' in parents and name = 'library.json'");if(files.length!==1)throw new Error(files.length?'Multiple library backups found. Resolve duplicates in Drive.':'No library.json backup found.');const data=await(await driveFetch('/files/'+encodeURIComponent(files[0].id)+'?alt=media')).json();validateBackup(data);mergeBackup(data);save();($('#drive-progress')||{}).textContent='Library merged. PDFs download from Drive when you open them. Newer local edits were preserved.';toast('Drive library restored and merged.')})}
function confirmAction(title,message,action){modal(modalTitle(title)+`<p>${esc(message)}</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=async()=>{try{await action();close();render()}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.collection)navigate('library',b.dataset.collection);if(b.hasAttribute('data-close'))close();if(b.dataset.paper)details(b.dataset.paper);if(b.dataset.external)details(b.dataset.external,true);if(b.dataset.star){const p=papers.find(p=>p.id===b.dataset.star);p.importance=p.importance==='high'?'normal':'high';p.updated=Date.now();save();render();}if(b.dataset.import)importPaper(b.dataset.import);if(b.dataset.cite)cite(b.dataset.cite);if(b.dataset.read)await readPdf(b.dataset.read);if(b.dataset.delete)confirmAction('Remove this paper?','This removes the citation, notes, and local PDF from this device. Your Drive backup is kept until your next backup.',async()=>{const p=papers.find(p=>p.id===b.dataset.delete);if(p.pdfId)await pdfStore('delete',p.pdfId);papers=papers.filter(item=>item.id!==p.id);save();toast('Paper removed.')});if(b.dataset.addTab){addMode=b.dataset.addTab;renderAdd()}if(b.dataset.layout){layout=b.dataset.layout;render()}if(b.dataset.discoverTopic){$('#discover-query').value=b.dataset.discoverTopic;searchDiscovery(b.dataset.discoverTopic)}if(['add-paper','empty-add'].includes(b.id))addPaper();if(['top-export','export-library'].includes(b.id))cite();if(b.id==='pick-paper')pickPaper();if(b.id==='drive-connect')navigate('settings');if(b.id==='remove-samples')confirmAction('Start with your own papers?','Remove the sample papers. Papers you added yourself will stay in your library.',()=>{papers=papers.filter(p=>!p.sample);save();toast('Sample papers removed.')});if(b.id==='add-collection'){modal(modalTitle('A new collection.')+'<form id="collection-form"><div class="field"><label for="collection-name">Collection name</label><input id="collection-name" required maxlength="60" placeholder="e.g. Post-quantum cryptography"></div><div class="modal-actions"><button class="button primary">Create collection</button></div></form>');$('#collection-form').onsubmit=e=>{e.preventDefault();const t=$('#collection-name').value.trim();if(!t)return;settings.collections=[...new Set([...(settings.collections||[]),t])];saveSettings();close();navigate('library',t);toast('Collection created. Add its tag to any paper.')}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});$('#modal').addEventListener('close',()=>{if(readerUrl){URL.revokeObjectURL(readerUrl);readerUrl=''}});
hydrate();const hash=location.hash.slice(1);if(hash.startsWith('collection=')){collection=decodeURIComponent(hash.slice(11))}else if(labels[hash])view=hash;render();

window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);const tag=h.startsWith('collection=')?decodeURIComponent(h.slice(11)):'';const next=tag?'library':(labels[h]?h:'library');if(next!==view||tag!==collection){view=next;collection=tag;query='';statusFilter='all';priorityFilter='all';render()}});
